def decrypt_openssl(data, passphrase, key_length=32):
    if data.startswith(b"Salted__"):
        salt = data[len(b"Salted__") : AES.block_size]
        key, iv = evp_bytestokey(passphrase, salt, key_length, AES.block_size)
        d = AES.new(key, AES.MODE_CBC, iv)
        out = d.decrypt(data[AES.block_size :])
        return unpad_pkcs5(out)

@classmethod
def encrypt_data(cls, data, key, iv):
    rkey = "".join(reversed(key)).encode("utf8")
    riv = "".join(reversed(iv)).encode("utf8")

    fkey = SHA256.new(rkey).hexdigest()[:32].encode("utf8")

    cipher = AES.new(fkey, AES.MODE_CBC, riv)
    encrypted = cipher.encrypt(pad(data, 16, "pkcs7"))
    return base64.b64encode(encrypted)

def decrypt_data(self, cipher_data, encrypted_data):
    cipher = AES.new(
        bytes(cipher_data["key"], "utf-8"),
        self.encryption_algorithm[cipher_data["algorithm"]],
        bytes(cipher_data["iv"], "utf-8"),
    )

    return unpad(cipher.decrypt(binascii.unhexlify(encrypted_data)), 16, "pkcs7")

